solution:
import { useState } from 'react';

export function useCharCount(max) {
  const [value, setValue] = useState('');
  return {
    value,
    onChange: (e) => setValue(e.target.value),
    remaining: max - value.length,
    isOverLimit: value.length > max,
  };
}
